export function getCountry(code: string): Country {
  const found = COUNTRIES.find((c) => c.code === code);
  if (!found) throw new Error(`Unknown country code: ${code}`);
  return found;
}

export function getCountriesByContinent(continent: ContinentId): Country[] {
  return COUNTRIES.filter((c) => c.continent === continent);
}

export function countCountriesByContinent(continent: ContinentId): number {
  return getCountriesByContinent(continent).length;
}

export function getCountriesByTier(tier: Tier): Country[] {
  return COUNTRIES.filter((c) => c.tier === tier);
}
